public static void main(Args _args)
{
    if(SysDataverseUtility::IsDataverseLinked())
    {
        IOrganizationService service;

        service = SysDataverseUtility::GetOrganizationServiceForCurrentUser(classStr(TMSSustainabilityServiceHealthChecker));

        QueryExpression x =  new QueryExpression("Environment Variable Values");

        FilterExpression crit = new FilterExpression();

        crit.AddCondition('Schema Name', ConditionOperator::Equal, 'CatalogSubscription');



        //x.Criteria.AddCondition('Schema Name', ConditionOperator::Equal, 'CatalogSubscription');

        var envVar = service.RetrieveMultiple(x);

        var entities = envVar.Entities;

        if(entities.Count > 0)
        {
            List collection = new List(Types::Record);

            ListEnumerator li = collection.getEnumerator();

            li.moveNext();

            while(li.current())
            {
                Entity entity = li.current();
                //info(entity.GetAttributeValue('asdf'));


                li.moveNext();
            }

        }
    }
}
